from __future__ import annotations

import logging
import re

from ..client.telnetclient import TelnetClient
from ..exception import (
    InvalidTelnetClient,
    NoRegexpMatch,
    PortIsReserved,
    ProcessCannotStart,
    WtsSimException,
)
from ..ssh import SshConnectionAdapter
from ..wts.edaemon import Edaemon
from .common import WtsSimCommon


class Egate(WtsSimCommon):
    """A class to handle the egate start/stop procedure and communication with the started egate."""

    def __init__(
        self,
        ssh_client: SshConnectionAdapter,
        telnet: TelnetClient,
        port: int,
        *args,
        **kwargs,
    ):
        """
        :param SshConnectionAdapter     ssh_client: Connected SSH client.
        :param TelnetClient telnet:     Telnet client used to interact with the egate application.
        :param integer      port:       Egate control port (Telnet interface).
        """
        super(Egate, self).__init__(*args, **kwargs)
        self.lua_dirs = []
        self._client = ssh_client
        self._telnet = telnet
        self._port = port
        self._edaemons = []
        self._log = logging.getLogger(__name__)

        self._check_client()
        self._check_telnet()

    @property
    def client(self) -> SshConnectionAdapter:
        """Client connected to the remote/local host

        :return: Client object
        """
        return self._client

    @property
    def is_running(self) -> bool:
        """Checks if an egate instance is running."""
        self._pid = self._client.execute_command(
            f'pgrep -f "./egate --port {self._port}"'
        )
        return True if self._pid[0] else False

    def add_edaemon(self, edaemon: Edaemon) -> None:
        """Add an edaemon instance for the common startup.

        :param Edaemon edaemon: Edaemon instance.
        """
        self._edaemons.append(edaemon)

    def setup(self, reconnect: bool = False) -> None:
        """Stop old instances and start a new egate instance if reconnect flag is not set.
           If reconnect flag is set, connect to existing egate instance.

        :note: Edaemon startup will be handled if at least one edaemon was added before the setup procedure.

        :param boolean reconnect:    Reconnects to an existing egate instance if flag is set.
                                     Default value is False.
        """
        self._started = True
        if reconnect:
            self._remove_old_logs()
            self.reset()
        else:
            self._kill_egate()
            self._remove_old_logs()
            self._setup_edaemons()
            self._start_egate()

    def configure_egate(
        self,
        cfg_file: str | None = None,
        suite_file: str | None = None,
        timeout: int | None = 60,
        retry: int = 0,
    ) -> None:
        """Configure the egate process through a pre-defined lua script.

        :param string  cfg_file:  Path to the lua configuration file.
        :param string  suite_file: Path to the lua suite file.
        :param integer timeout:   Timeout for this operation. Default is 60 seconds.
        :param int retry:        Number of times the user want to retry the process.
        """
        for count in range(retry + 1):
            try:
                if cfg_file is not None:
                    cmd = f"cfg file={cfg_file}"
                    self._log.debug(
                        self.execute_telnet_command(
                            cmd, pass_regexp="CHANGE STATE: CONFIGURED", timeout=timeout
                        )
                    )
                elif suite_file is not None:
                    cmd = f"cfg suite={suite_file}"
                    self._log.debug(
                        self.execute_telnet_command(
                            cmd, pass_regexp="CHANGE STATE: CONFIGURED", timeout=timeout
                        )
                    )
                return
            except WtsSimException as e:
                self._log.debug(str(e))
        else:
            raise ProcessCannotStart(
                f"Could not process egate after {1 + retry} attempt(s)"
            )

    def start_services(
        self, timeout: int | None = 180, check_version: bool = True
    ) -> None:
        """Start configured egate services.

        :param integer timeout: Timeout for this operation. Default is 180 seconds.
        :param boolean check_version: Flag indicating whether to check the version of the egate.
        """
        start_command = f'start version_check={"on" if check_version else "off"}'
        self._log.debug(
            self.execute_telnet_command(
                start_command, pass_regexp="CHANGE STATE: ACTIVE", timeout=timeout
            )
        )

    def retry_services(
        self, timeout: int = 180, retry: int = 2, check_version: bool = True
    ) -> None:
        """Retry Start configured egate services.

        :param integer timeout: Timeout for this operation. Default is 180 seconds.
        :param integer retry: Number of times you want to  retry start_services. Default is 2
        :param boolean check_version: Flag indicating whether to check the version of the egate.
        """
        retry = 2 if retry == 1 else retry
        for _ in range(retry):
            try:
                self._log.info(
                    self.start_services(timeout=timeout, check_version=check_version)
                )
                if self.check_enb_state("ACTIVE"):
                    break
            except NoRegexpMatch as e:
                self._log.info(str(e))
        else:
            raise ProcessCannotStart(
                f"Could not start Egate Services after {retry} attempt(s)"
            )

    def check_enb_state(self, state: str) -> bool:
        """Checks if the state of eNB

        :param string state:  Use to compare the state of eNB
        :return: True if the state of eNB returned is equal to the param state else False
        :rtype: bool
        """
        enb_state = self.execute_telnet_command(
            cmd="state", pass_regexp="EGATE>", ignore_prompt_prefix=True
        )
        status = re.search(state, enb_state, re.M | re.I)
        return True if status else False

    def execute_telnet_command(
        self,
        cmd: str,
        pass_regexp: str | None = None,
        fail_regexp: str | None = None,
        timeout: int | None = None,
        ignore_prompt_prefix: bool | None = None,
        return_output: bool | None = True,
        **kwargs,
    ) -> str:
        """Execute an egate command via the Telnet client.

        :param string  cmd:                   Command to execute.
        :param boolean return_output:         Flag indicating whether egate log should be printed out.
        :param string  pass_regexp:           Regexp indicating that command passed.
        :param string  fail_regexp:           Regexp indicating that command failed.
        :param integer timeout:               Timeout for this operation. Default is 10 seconds.
        :param boolean ignore_prompt_prefix:  Prompts before data will be ignored if True.

        :return: Data received during execution, truncated as necessary. Valid only if pass_regexp is set.
        :rtype: string
        """
        timeout = 10 if timeout is None else timeout
        self._open_telnet_connection()
        self._send_telnet_command(cmd)
        out = self._read_telnet_response(
            pass_regexp, fail_regexp, timeout, ignore_prompt_prefix, **kwargs
        )
        out += self._telnet.read()
        self._close_telnet_connection()
        return out if bool(return_output) else ""

    def reset(self, timeout: int = 30) -> None:
        """Reset a configured egate.

        :param integer timeout: Timeout for this operation. Default is 30 seconds.

        :note: Reset method is needed to reconfigure an egate process.
        """
        self._log.debug(self.execute_telnet_command("reset"))
        self._log.debug(
            self.execute_telnet_command(
                "state", pass_regexp="The state is INIT", timeout=timeout
            )
        )

    def teardown(self) -> None:
        """Stop egate and clean the environment.

        :note: Edaemons will be torn down if at least one edaemon instance was added.
        """
        self._started = False
        self._shutdown_egate()
        self._kill_egate()
        self._teardown_edaemons()

    def _open_telnet_connection(self):
        self._log.debug(
            f"WTSSIM opens connection: {self._telnet.host}:{self._telnet.port}"
        )
        self._telnet.open_connection()

    def _close_telnet_connection(self):
        self._log.debug(
            f"WTSSIM closes connection: {self._telnet.host}:{self._telnet.port}"
        )
        self._telnet.close_connection()

    def _send_telnet_command(self, cmd):
        self._log.info(f"WTSSIM executes telnet cmd: {cmd}")
        self._telnet.write_bare(f"{cmd}\r\n")

    def _read_telnet_response(
        self, pass_regexp, fail_regexp, timeout, ignore_prefix, **kwargs
    ):
        if pass_regexp is None and fail_regexp is None:
            return self._telnet.read()

        regexp = self._prepare_searching_regexp(pass_regexp, fail_regexp)
        regex_found, out = self._telnet.read_until_regexp(
            regexp, ignore_prefix, timeout, **kwargs
        )

        if pass_regexp and regex_found is False:
            raise NoRegexpMatch(
                f"It was not possible to find string after {timeout} secs to match "
                f"regexp ({pass_regexp}) in output\n({out})"
            )

        if fail_regexp:
            if re.search(fail_regexp, out):
                raise NoRegexpMatch(
                    f"Fail regexp found ({fail_regexp}) in output\n({out})"
                )

        return out

    def _prepare_searching_regexp(self, pass_regexp, fail_regexp):
        if pass_regexp is not None and fail_regexp is not None:
            return f"{pass_regexp}|{fail_regexp}"
        elif pass_regexp is not None and fail_regexp is None:
            return pass_regexp
        elif pass_regexp is None and fail_regexp is not None:
            return fail_regexp

    def _extend_lua_path(self) -> str:
        lua_dirs_string = self._convert_lua_path_to_string()
        cmd = f"echo $LUA_PATH; export LUA_PATH='{lua_dirs_string}{self._tool_dir}/?.lua;'; "
        return cmd

    def _convert_lua_path_to_string(self) -> str:
        if self._is_number_of_lua_dirs_entries(0):
            return ""
        elif self._is_number_of_lua_dirs_entries(1):
            return f"{self.lua_dirs[0]}/?.lua;"
        else:
            return "/?.lua;".join(self.lua_dirs) + "/?.lua;"

    def _is_number_of_lua_dirs_entries(self, number: int) -> bool:
        if len(self.lua_dirs) == number:
            return True
        return False

    def _kill_egate(self) -> None:
        if self._pid is not None:
            self._kill_process()
        else:
            self._kill_unknown_egate()
        self._pid = None

    def _kill_unknown_egate(self) -> None:
        self._kill_process(process_cmd=rf"egate\s*--port\s*{self._port}")

    def _remove_old_logs(self) -> None:
        self._client.execute_command(
            f"cd {self._tool_dir}; sudo rm -rf egate*.log.*; sudo rm -rf error*log"
        )

    def _setup_edaemons(self) -> None:
        for each in self._edaemons:
            each.setup()

    def _start_egate(self) -> None:
        if not self._is_tcp_port_free(self._port):
            raise PortIsReserved("Egate", self._port)
        cmd = self._extend_lua_path()
        if not self._pid:
            cmd += f"cd {self._tool_dir}; ./egate --port {self._port}"
            out, err, rc = self._client.execute_command(cmd)
            self._pid = self._get_egate_pid(out, err)

    def _get_egate_pid(self, out: str, err: str) -> str:
        found = re.search(r"EGATE:\s*SERVER\s*PID\s*=\s*(.*)", out)
        if not found:
            raise ProcessCannotStart(
                "Cannot start the egate process and shell output is:", out, err
            )
        return found.groups()[0].strip()

    def _teardown_edaemons(self) -> None:
        for each in self._edaemons:
            each.teardown()

    def _shutdown_egate(self) -> None:
        try:
            self.execute_telnet_command("reset")
            self.execute_telnet_command("shutdown")
        except TelnetClient.SOCKET_CONN_ERROR as e:
            self._log.debug(e)
        except EOFError as e:
            self._log.debug(e)

    def _check_telnet(self) -> None:
        if not (
            hasattr(self._telnet, "open_connection")
            or hasattr(self._telnet, "close_connection")
        ):
            raise InvalidTelnetClient(
                "Provided telnet must have a 'open_connection' and 'close_connection' method"
            )
